sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-23: keep reservation.violation_count accurate (current and previous reservation)
    function recount(resId) {
        if (!resId) {
            return;
        }
        var agg = new GlideAggregate('x_1850693_enterp_0_violation');
        agg.addQuery('reservation', resId);
        agg.addAggregate('COUNT');
        agg.query();
        var count = agg.next() ? parseInt(agg.getAggregate('COUNT'), 10) : 0;
        var res = new GlideRecord('x_1850693_enterp_0_reservation');
        if (res.get(resId) && parseInt(res.getValue('violation_count') || '0', 10) != count) {
            res.setValue('violation_count', count);
            res.update();
        }
    }
    recount(current.getValue('reservation'));
    if (previous && previous.getValue('reservation') != current.getValue('reservation')) {
        recount(previous.getValue('reservation'));
    }
})(current, previous);
